// Build HTML patch cycle report
const items = $input.all();
const succeeded = items.filter(i => i.json.state === 'Succeeded');
const failed = items.filter(i => i.json.state === 'Failed');
const pending = items.filter(i => !['Succeeded','Failed'].includes(i.json.state));

const total = items.length;
const pctOk = total ? Math.round(succeeded.length / total * 100) : 0;
const statusColor = failed.length === 0 ? '#27ae60' : '#e74c3c';
const statusText = failed.length === 0 ? 'ALL PATCHES SUCCEEDED' : `${failed.length} FAILURE(S) DETECTED`;

let failureRows = '';
for (const f of failed) {
  const name = f.json.endpointName || f.json.endpointId || 'Unknown';
  const error = (f.json.errorMessage || f.json.statusDetail || 'No detail available').replace(/</g, '&lt;');
  const group = f.json.logicalGroupName || f.json.logicalGroupId || '-';
  failureRows += `<tr><td style="padding:8px;border:1px solid #ddd">${name}</td><td style="padding:8px;border:1px solid #ddd">${error}</td><td style="padding:8px;border:1px solid #ddd">${group}</td></tr>`;
}

const failureTable = failed.length > 0
  ? `<h3 style="color:#e74c3c;margin-top:24px">Failed Endpoints</h3>
<table style="border-collapse:collapse;width:100%;font-size:14px">
<thead><tr style="background:#f8f9fa">
<th style="padding:8px;border:1px solid #ddd;text-align:left">Endpoint</th>
<th style="padding:8px;border:1px solid #ddd;text-align:left">Error</th>
<th style="padding:8px;border:1px solid #ddd;text-align:left">Group</th>
</tr></thead>
<tbody>${failureRows}</tbody></table>`
  : '';

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"></head><body style="font-family:Segoe UI,Arial,sans-serif;max-width:700px;margin:0 auto;padding:20px">
<h2 style="margin-bottom:4px">Patch Tuesday Report</h2>
<p style="color:#666;margin-top:0">${new Date().toLocaleDateString('en-GB',{weekday:'long',year:'numeric',month:'long',day:'numeric'})}</p>
<div style="background:${statusColor};color:#fff;padding:16px 20px;border-radius:6px;font-size:18px;font-weight:600;margin:16px 0">${statusText}</div>
<table style="border-collapse:collapse;width:100%;font-size:14px;margin:12px 0">
<tr><td style="padding:8px;border:1px solid #ddd;font-weight:600;background:#f8f9fa;width:160px">Total endpoints</td><td style="padding:8px;border:1px solid #ddd">${total}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;font-weight:600;background:#f8f9fa">Succeeded</td><td style="padding:8px;border:1px solid #ddd;color:#27ae60;font-weight:600">${succeeded.length} (${pctOk}%)</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;font-weight:600;background:#f8f9fa">Failed</td><td style="padding:8px;border:1px solid #ddd;color:${failed.length?'#e74c3c':'#27ae60'};font-weight:600">${failed.length}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd;font-weight:600;background:#f8f9fa">Pending / Running</td><td style="padding:8px;border:1px solid #ddd;color:#f39c12">${pending.length}</td></tr>
</table>
${failureTable}
<p style="color:#999;font-size:12px;margin-top:24px">Generated by n8n + baramundi bConnect connector</p>
</body></html>`;

return [{ json: { html, total, succeeded: succeeded.length, failed: failed.length, pending: pending.length } }];
